 spiTor=(k,ax,x,y,z,R,r,c,o)=>{const n=40,pts=[];for(let i=0;i<n;i++){const a=i/n*Math.PI*2,u=Math.cos(a)*R,v=Math.sin(a)*R;pts.push(ax==="x"?[x,y+u,z+v]:ax==="y"?[x+u,y,z+v]:[x+u,y+v,z])}return spiSw(k,pts,r,c,Object.assign({closed:1,seg:14},o))},
 spiCyl=(k,ax,x,y,z,len,r,c,o,r2)=>g3C(k,ax,x,y,z,len,r,c,Object.assign({seg:36,m:.5},o),r2),
 spiBox=(k,x,y,z,w,h,d,c,o)=>g3B(k,x,y,z,w,h,d,c,Object.assign({r:Math.min(w,h,d)*.06,m:.4},o)),
