 if(m=/SCH\s?(\d+)/.exec(raw))P.sch=+m[1];else if(/\bSTD\b/.test(raw))P.sch="STD";
 if(m=/(\d+(?:\.\d+)?)MM ID/.exec(raw))P.id=+m[1];if(m=/(\d+(?:\.\d+)?)MM CS/.exec(raw))P.cs=+m[1];
 if(m=/(\d+(?:-\d+\/\d+)?|\d+\/\d+)INX(\d+)MM/.exec(raw)){P.sd=spiFrac(m[1])*25.4;P.sl=+m[2]}
 if(m=/\bM(\d+)X(\d+)MM/.exec(raw)){P.sd=+m[1];P.sl=+m[2]}
 if(m=/,(\d+),(\d+)T,(\d+)W,(\d+)L/.exec(raw)){P.bt=+m[2];P.bw=+m[3];P.bl=+m[4]}
 if(m=/(\d+)T,(\d+)KG\/M3(?:,(\d+)C)?/.exec(raw)){P.ft=+m[1];P.fd=+m[2];P.fc=m[3]?+m[3]:null}
 if(m=/(\d+(?:\.\d+)?)X(\d+)LG/.exec(raw)){P.td=+m[1];P.tl=+m[2]}
 if(m=/(\d+)\s?IN DIAL/.exec(raw))P.dial=+m[1];
 if(m=/(\d+)MICRON/.exec(raw))P.micron=+m[1];
 if(m=/(\d+)MMX(\d+)M\b/.exec(raw)){P.tw=+m[1];P.tlen=+m[2]}
 if(m=/(\d+(?:\.\d+)?)\s?(L|KG|ML)\b/.exec(raw))P.qty=m[1]+" "+m[2].toLowerCase().replace("ml","ml");
